package io.knowledgebrain.space;
import java.time.*;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class ActivityAuthorizationTest {
 MockHttpServletRequest request(){var r=new MockHttpServletRequest();r.setSecure(true);r.addHeader("Authorization","Bearer "+"a".repeat(43));return r;}
 @Test void freshGuestRegisteredAndViewerAccessRequiresPrivatePersonalSpace(){var spaces=mock(PersonalSpaceStore.class);var identity=mock(IdentityPrincipalClient.class);var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();var api=new ActivityAuthorizationController(spaces,identity,"a".repeat(43));for(var kind:new String[]{"GUEST","REGISTERED"}){when(identity.resolve("b".repeat(43),null)).thenReturn(new IdentityPrincipalClient.Principal(actor,kind,Instant.now().plusSeconds(60)));when(spaces.visible(space,actor)).thenReturn(new PersonalSpaceStore.SpaceView(space,"PERSONAL","PRIVATE","VIEWER"));var result=api.authorize(new ActivityAuthorizationController.Check(space,"b".repeat(43),"TIMELINE_READ"),request());assertEquals(actor,result.getBody().principalId());assertEquals("no-store",result.getHeaders().getCacheControl());}when(spaces.visible(space,actor)).thenReturn(null);assertThrows(ResponseStatusException.class,()->api.authorize(new ActivityAuthorizationController.Check(space,"b".repeat(43),"TIMELINE_READ"),request()));when(spaces.visible(space,actor)).thenReturn(new PersonalSpaceStore.SpaceView(space,"PUBLIC","PUBLIC","VIEWER"));assertThrows(ResponseStatusException.class,()->api.authorize(new ActivityAuthorizationController.Check(space,"b".repeat(43),"TIMELINE_READ"),request()));}
 @Test void browserCookieOtherDomainActionsAndWrongCapabilitiesAreRejected(){var spaces=mock(PersonalSpaceStore.class);var identity=mock(IdentityPrincipalClient.class);var api=new ActivityAuthorizationController(spaces,identity,"a".repeat(43));var space=new UuidV7(Clock.systemUTC()).next();var cookie=request();cookie.addHeader("Cookie","__Host-brain_guest=anything");assertThrows(ResponseStatusException.class,()->api.authorize(new ActivityAuthorizationController.Check(space,"b".repeat(43),"TIMELINE_READ"),cookie));for(var action:new String[]{"ROADMAP_WRITE","NOTE_READ","BRAIN_SEARCH"})assertThrows(ResponseStatusException.class,()->api.authorize(new ActivityAuthorizationController.Check(space,"b".repeat(43),action),request()));var wrong=request();wrong.removeHeader("Authorization");wrong.addHeader("Authorization","Bearer "+"c".repeat(43));assertThrows(ResponseStatusException.class,()->api.authorize(new ActivityAuthorizationController.Check(space,"b".repeat(43),"TIMELINE_READ"),wrong));verifyNoInteractions(spaces,identity);}
}
